import { Component } from '@angular/core';
import { AuthGuardService } from 'src/app/services/auth-guard.service';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';

@Component({
  selector: 'app-sidenav',
  templateUrl: './sidenav.component.html',
  styleUrls: ['./sidenav.component.scss']
})
export class SidenavComponent {

  userDetails : any;
  logo  = `
  data:image/png;base64,
  `

  linkActive : any = {
    "dashboard" : true,
    "billing" : false,
    "clients" : false,
    "services" : false,
    "expenses" : false,
    "balance" : false,
    "followup" : false,
    "employee":  false
  }
  constructor(public authService:AuthGuardService, private sanitizer: DomSanitizer){
    this.userDetails = this.authService.getUserDetails();
    // console.log(this.userDetails?.app_meta_details?.billingdetails?.signature)
  }

  sanitizeImageURL(base64URL: string): SafeUrl {
    return this.sanitizer.bypassSecurityTrustUrl(base64URL);
  }

  onClickLink(link:string){
    for(let li in this.linkActive){
      if(li == link){
        this.linkActive[li] = true;
      }else{
        this.linkActive[li] = false;
      }
    }
  }
}
